import math
from collections import defaultdict

def parse_input():
    m, t, p = map(int, input().split())
    n = 1 << m
    e0 = list(map(int, input().split()))
    b = list(map(int, input().split()))
    return m, t, p, n, e0, b

def compute_energy(values, b, i, k, t):
    for i in range(len(values)):
        values[i] = (values[i] * b[-k]) % t
        for j in range(k, -1, -1):
            values[i] = (values[i] + (values[i ^ ((1 << j) - 1)] * b[j])) % t
    return values

def process_input(m, t, p, n, e0, b):
    solutions = defaultdict(list)
    boundary_chains = set()
    for i in range(m + 1):
        b_next = [0] * (m + 1)
        for j in range(m + 1 - (1 << i), m):
            b_next[i] += 1
        system = b_next + b

        for k in range(n // 2):
            boundary_chains.add((k << i) & (n - 1))
            # Avoid dividing by zero
            if system[i] == 0:
                solutions[(k << i) & (n - 1)].append((k << i) & (n - 1))
                values0 = [pow(4, i, p) if k else e0[_] for _ in range((n + 1) >> i)]
                solutions[(k << i) & (n - 1)].append(compute_energy(values0[:m + 1], system, i, k, p))
            else:
                half = min((k << i), n >> i)
                solutions[(k << i) & (n - 1)].append(min(compute_energy(values0[:m], system[:m], i, half, p), compute_energy(values0[:m], system[:m], i, (n >> i) - half - 1, p)))
        for k in range(-2, -n // 2 - 1, -1):
            old_k = k + (1 << i)
            if old_k in boundary_chains:
                solutions[old_k].append([])

    return solutions[(0, 0, 0)]

def main(m, t, p, n, e0, b):
    solutions = process_input(m, t, p, n, e0, b)
    assert len(solutions) == 1

    output = ['']
    nmt = 1 << m
    for i in range(nmt):
        output.append(str(solutions[(i, 0, 0)][0][0]))

if __name__ == '__main__':
    m, t, p, n, e0, b = parse_input()
    main(m, t, p, n, e0, b)
    print('\n'.join(output))
