        nonlocal result, min_cost
        total_cost = 0
        cost = 1 / sum(prices[i] for i in g[x])
        if min_cost > cost:
            min_cost = cost
        for y, _ in g[x]:
            if y == parent:
                continue
            dfs(y, x)
            total_cost += prices[y]
        total_cost += 1 - sum(invs[y] for y in weights) * total_cost
        result = min(result, total_cost)
        return total_cost

    status = [False] * n
