def is_holy_triplet(point1, point2, point3):
    x1, y1 = point1
    x2, y2 = point2
    x3, y3 = point3
    # Compute the area of the triangle formed by the points
    area = abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2
    # For the points to be antipodal, the area should be less than or equal to 0
    return area <= 0

