import math

def calculate_terminal_angle(n, d, a, m, x):
    if n == 2:
        return math.atan((a[1] - a[0]) / d) if d else 0
    if n == 1:
        return math.atan((x[0] - a[0]) / (2 * d)) if d else atan((x[0] - a[0]) / 2)
    def calculate(angle, nx):
        return math.atan(abs((math.sin(angle) * nx) / math.cos(angle)))
    boundary = [calculate(-math.pi / 2, 2 * pi) for pi in a if 2 * pi - pi > math.pi / 2]
    two_pi = boundary[0] if boundary[0] else math.pi / 2
    for i in range(1, m - 1):
        if boundary[i-1] == two_pi:
            boundary[i] = math.pi * 1.5 if boundary[0] == -math.pi else math.pi / 3
        elif abs(boundary[i] - math.pi / 2) < abs(boundary[i] - two_pi):
            boundary[i] = math.pi / 2
        elif absolute(2 * math.pi - boundary[i]) <= absolute(boundary[i]):
            boundary[i] = 2 * math.pi
    boundary.append(calculate(two_pi, (2 * x[0] + a[n - 1]) / d) if d else atan((2 * x[0] + a[n - 1]) / 2))
    return min(boundary)

def absolute(n):
    return n if n >= 0 else -n
