from collections import defaultdict, deque
import heapq

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def find_min_cycle_length(graph):
    n = len(graph)
    distances = {node: float('infinity') for node in graph}

    for start_node in graph:
        distances[start_node] = 0

        while not all(val == 0 for val in distances.values()):
            prev_node = None
            min_distance = float('infinity')

            for node in graph:
                if node == start_node:
                    continue

                if distances[start_node] + graph[start_node][node] < distances[node]:
                    prev_node = node
                    min_distance = distances[start_node] + graph[start_node][node]

            if prev_node:
                distances[prev_node] = min_distance
            else:
                break

    min_cycle = float('infinity')
    for distances in map(dijkstra, graph.values()):
        if max(max(val - 1 for val in distances.values()), distances[min(distances)]) > min(distances):
            min_cycle = min(min_cycle, max(max(val - 1 for val in distances.values()), distances[min(distances)]), key=min)

    return min_cycle

