import math

def calculate_terminal_angle(d, a, buildings, x):
    seen = {}
    for i in range(1, len(buildings)):
        if buildings[i] - buildings[i - 1] > d:
            break
        if i % 2 == 0 and buildings[i] - buildings[i - 1] == d:
            # Trapezium type bend
            y = math.sqrt((a[i] + a[i - 1]) / 2 * (a[i] + a[i - 1]) + d * d)
            angle = math.degrees(math.atan2(a[i] - 0.5 * (a[i] + a[i - 1]), y - 0.5 * (y + (a[i] + a[i - 1])))
            return math.radians(angle)
        elif i % 2 == 1 and buildings[i] - buildings[i - 1] == d:
            # Rectangle Type bend
            angle = math.degrees(math.atan2(abs(a[i] - a[i - 1]), 0.5 * (a[i] - a[i - 1])))
            continue
        else:
            continue

    angle = math.degrees(math.atan2(buildings[0] - 0.5 * (a[0] + a[1]), x - 0.5 * (a[0] + a[1])))
    return math.radians(angle)

