    sorted_chars = sorted(chars, key=lambda x: [0]*d + [x])
    return ''.join(sorted_chars)

def modify_string(s, k, d):
    # Apply d-sorting to the substring s[(i+1)..(i+k)]
    if k < d:
        for strip in range(1, (k+1)//d):
            modified_str = s[(strip*d + 1):strip*d + k + 1]
            for char in modified_str:
                pos = (int(char) % d) * (strip * d + 1 - (int(char) % d) + 1)
                bisect.insort_left(s, char, bisect_left(s, created_from_pos) if created_from_pos else bisect_left(s, char))
                # created_from_pos is used for creating characters
    return s

def process_queries(s, queries):
    for query in queries:
        k, d = query
        s = modify_string(s, k, d)
        print(s)

# Example usage
s = "qwerty"
m = 3
queries = [(4, 2), (6, 3), (5, 2)]

process_queries(s, m)
