def is_almost_increasing_a_sequence(start, end, a):
    for i in range(start, end):
        if a[i] >= a[i+1]:
            return False
    return a[end] > a[start]

def is_replacements_needed(start, end, a):
    changes = 0
    for i in range(start, end):
        if a[i+1] - a[i] > 1:
            changes += 1
    return changes
