def is_holy_triplet(i, j, k, points):
    # Calculate the cross product of vectors XY and XZ
    cross_product = (points[k][1] - points[j][1]) * (points[i][0] - points[j][0]) - (points[k][0] - points[j][0]) * (points[i][1] - points[j][1])
    # If cross product is zero, points do not form a triangle with Pj as a common point
    return cross_product != 0

def count_holy_triplets(N, points):
    count = 0
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                if is_holy_triplet(i, j, k, points):
                    count += 1
    return count

