import sys
from typing import List

def parse_lines(input: List[str]) -> List[List[int]]:
    polygons = []
    for line in input:
        pts = [int(s) for s in line.replace(" ", "").split()]
        polygons.append([pts[0], pts[1], pts[2], pts[3], pts[4], pts[5], pts[6], pts[7]])
    return polygons

def generate_polygon_areas(polygons: List[List[int]]) -> int:
    return int(sum([area(pt1, pt2, pt3, pt4) for pt1, pt2, pt3, pt4 in polygons]) * 0.5)

def area(p1: int, p2: int, p3: int, p4: int) -> float:
    return abs((p1[0] - p4[0]) * (p2[1] - p3[1]) - (p1[1] - p4[1]) * (p2[0] - p3[0])) / 2.

def mean_score(faces: int) -> float:
    return sum([catch(score, polygons) for score in range(1, faces + 1)]) / faces

def catch(score: int, polygons: List[List[int]]) -> float:
    integral = 0
    for polygon in polygons:
        integral += area(polygon[0], polygon[1], polygon[2], polygon[3]) * score
    return integral

def main():
    input = sys.stdin.read().splitlines()
    polygons = parse_lines(input)
    with open("testframe.json", "w") as f:
        f.write(json.dumps({  'polygons': polygons,  'catch': catch }))
    print(faces, mean_score(faces))

if __name__ == "__main__":
    main()
